/bin/bash -lc "python3 -c \"
from PIL import Image
import numpy as np
a = np.array(Image.open('first_frame.png')).astype(int)
H,W,_=a.shape
# print dominant hue label per 8x8 cell
for y in range(0,144,8):
    line=''
    for x in range(0,256,8):
        blk=a[y:y+8,x:x+8].mean(0).mean(0)
        r,g,b=blk
        if max(blk)-min(blk)<18:
            line+='K' if r<60 else ('w' if r>180 else 'g')
        elif r>b+25 and g>b+20:
            line+='Y'
        elif b>r+20 and b>g+10:
            line+='B'
        elif r>g+15 and r>b+15:
            line+='R'
        elif g>r+10 and g>b+10:
            line+='G'
        else:
            line+='?'
    print(line)
\""
